mapper.select:
SELECT ea.*, e.real_name AS expertName, e.research_field AS expertField, p.project_name AS projectName FROM expert_assignment ea LEFT JOIN expert e ON ea.expert_id = e.expert_id LEFT JOIN project p ON ea.project_id = p.project_id
AND ea.project_id = #{projectId}
AND ea.stage = #{stage}
ORDER BY ea.assign_time DESC
